import { useState } from 'react';
import { Plus, X } from 'lucide-react';
import { normalizeBaseUrl, safePath } from '@/model/security';
import type { AgentSourceConfig, AgentSourceKind, AuthMode } from '@/model/types';
import type { TFunction } from '@/i18n';

interface Props {
  open: boolean;
  onClose(): void;
  onAdd(source: AgentSourceConfig, sessionBearer?: string): void;
  t: TFunction;
}

const KINDS: { value: AgentSourceKind; labelKey: string; helpKey: string }[] = [
  { value: 'openai-compatible', labelKey: 'kind.openaiCompatible', helpKey: 'kind.help.models' },
  { value: 'custom-health', labelKey: 'kind.customHealth', helpKey: 'kind.help.health' },
  { value: 'openhouse-probe', labelKey: 'kind.openHouseProbe', helpKey: 'kind.help.openHouse' },
  { value: 'mcp-http', labelKey: 'kind.mcpHttp', helpKey: 'kind.help.mcp' },
];

export function AddAgentDialog({ open, onClose, onAdd, t }: Props) {
  const [kind, setKind] = useState<AgentSourceKind>('openai-compatible');
  const [name, setName] = useState('');
  const [baseUrl, setBaseUrl] = useState('');
  const [healthPath, setHealthPath] = useState('/health');
  const [authMode, setAuthMode] = useState<AuthMode>('none');
  const [token, setToken] = useState('');
  const [err, setErr] = useState<string | null>(null);
  if (!open) return null;
  return <div className="oh-modal-backdrop" role="dialog" aria-modal="true">
    <form className="oh-modal" onSubmit={(e) => {
      e.preventDefault();
      try {
        const normalized = normalizeBaseUrl(baseUrl);
        const now = Date.now();
        const id = `src-${now.toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
        onAdd({
          id,
          kind,
          name: name.trim() || inferName(normalized),
          baseUrl: normalized,
          healthPath: kind === 'custom-health' || kind === 'mcp-http' ? safePath(healthPath, '/health') : undefined,
          enabled: true,
          authMode,
          createdAt: now,
          updatedAt: now,
        }, authMode === 'session-bearer' ? token : undefined);
        setName(''); setBaseUrl(''); setToken(''); setAuthMode('none'); setErr(null); onClose();
      } catch (error) {
        setErr(error instanceof Error ? error.message : String(error));
      }
    }}>
      <div className="oh-modal-head"><h2>{t('dialog.title')}</h2><button type="button" onClick={onClose}><X size={18} /></button></div>
      <label>{t('dialog.connectorType')}<select value={kind} onChange={(e) => setKind(e.target.value as AgentSourceKind)}>{KINDS.map((k) => <option key={k.value} value={k.value}>{t(k.labelKey)} — {t(k.helpKey)}</option>)}</select></label>
      <label>{t('dialog.name')}<input value={name} onChange={(e) => setName(e.target.value)} placeholder={t('dialog.namePlaceholder')} /></label>
      <label>{t('dialog.baseUrl')}<input value={baseUrl} onChange={(e) => setBaseUrl(e.target.value)} placeholder={t('dialog.baseUrlPlaceholder')} required /></label>
      {(kind === 'custom-health' || kind === 'mcp-http') && <label>{t('dialog.healthPath')}<input value={healthPath} onChange={(e) => setHealthPath(e.target.value)} placeholder="/health" /></label>}
      <label>{t('dialog.authMode')}<select value={authMode} onChange={(e) => setAuthMode(e.target.value as AuthMode)}><option value="none">{t('dialog.authNone')}</option><option value="session-bearer">{t('dialog.authSessionBearer')}</option></select></label>
      {authMode === 'session-bearer' && <label>{t('dialog.sessionBearer')}<input type="password" value={token} onChange={(e) => setToken(e.target.value)} placeholder={t('dialog.sessionBearerPlaceholder')} /></label>}
      {err && <p className="oh-form-error">{err}</p>}
      <footer><button type="button" onClick={onClose}>{t('dialog.cancel')}</button><button className="primary"><Plus size={16} />{t('dialog.addResident')}</button></footer>
    </form>
  </div>;
}

function inferName(url: string): string {
  try { return new URL(url).hostname; } catch { return 'External agent'; }
}
