import { useCallback, useEffect, useMemo, useState } from 'react';
import { Plus, RefreshCw } from 'lucide-react';
import type { AppDb } from '@tytus/host-api';
import { normalizeTytusAgents } from '@/model/normalizeTytus';
import type { AgentCapability, AgentSourceConfig, AgentSourceKind, OpenHouseAgent, ProbeHistoryRow, SessionSecrets } from '@/model/types';
import { probeExternalSource, probeTytusPod } from '@/connectors/probe';
import { addHistory, deleteSource, listHistory, listLayout, listSources, upsertSource } from '@/repo/repo';
import { HouseScene } from '@/components/HouseScene';
import { AddAgentDialog } from '@/components/AddAgentDialog';
import { styles } from './styles';
import type { OpenHouseProps } from '@/model/types';
import { useOpenHouseI18n, type TFunction } from '@/i18n';

type Filter = 'all' | AgentSourceKind | 'issues' | 'online';

interface AbilityCard {
  title: string;
  body: string;
}

export function OpenHouse({ host }: OpenHouseProps) {
  const { t } = useOpenHouseI18n(host);
  const [db] = useState<AppDb>(() => host.storage.current());
  const [tytusAgents, setTytusAgents] = useState<OpenHouseAgent[]>(() => normalizeTytusAgents(host.daemon.state.agents, host.daemon.state.included));
  const [sources, setSources] = useState<AgentSourceConfig[]>([]);
  const [externalAgents, setExternalAgents] = useState<OpenHouseAgent[]>([]);
  const [history, setHistory] = useState<ProbeHistoryRow[]>([]);
  const [selectedId, setSelectedId] = useState<string | undefined>();
  const [filter, setFilter] = useState<Filter>('all');
  const [addOpen, setAddOpen] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [probingId, setProbingId] = useState<string | null>(null);
  const [sessionSecrets, setSessionSecrets] = useState<SessionSecrets>({ bearerBySourceId: {} });

  useEffect(() => {
    let alive = true;
    void Promise.all([listSources(db), listLayout(db), listHistory(db)]).then(([s, , h]) => {
      if (!alive) return;
      setSources(s);
      setHistory(h);
    });
    return () => { alive = false; };
  }, [db]);

  useEffect(() => host.daemon.onStateChange((state) => {
    setTytusAgents(normalizeTytusAgents(state.agents, state.included));
  }), [host]);

  const refreshExternal = useCallback(async (nextSources = sources, secrets = sessionSecrets) => {
    setRefreshing(true);
    try {
      const enabled = nextSources.filter((s) => s.enabled);
      const results: OpenHouseAgent[] = [];
      for (const batch of chunks(enabled, 4)) {
        const settled = await Promise.all(batch.map((source) => probeExternalSource(source, secrets)));
        results.push(...settled);
        setExternalAgents([...results]);
        for (const agent of settled) await persistProbe(db, agent);
      }
      setExternalAgents(results);
      setHistory(await listHistory(db));
    } finally {
      setRefreshing(false);
    }
  }, [db, sessionSecrets, sources]);

  useEffect(() => {
    if (sources.length) void refreshExternal(sources, sessionSecrets);
    // Probe loaded external sources once. Secret updates are explicit through add flow.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sources.length]);

  const allAgents = useMemo(() => [...tytusAgents, ...externalAgents], [tytusAgents, externalAgents]);
  const visibleAgents = useMemo(() => {
    if (filter === 'all') return allAgents;
    if (filter === 'issues') return allAgents.filter(isIssue);
    if (filter === 'online') return allAgents.filter((a) => a.status === 'online' || a.status === 'busy');
    return allAgents.filter((a) => a.sourceKind === filter);
  }, [allAgents, filter]);
  const selected = allAgents.find((a) => a.id === selectedId) ?? visibleAgents[0] ?? allAgents[0];
  const selectedHistory = history.filter((h) => h.agentId === selected?.id).slice(-4).reverse();
  const selectedAbilities = selected ? agentAbilities(selected, t) : [];

  useEffect(() => {
    if (!selectedId && visibleAgents[0]) setSelectedId(visibleAgents[0].id);
  }, [selectedId, visibleAgents]);

  const addSource = useCallback((source: AgentSourceConfig, sessionBearer?: string) => {
    const nextSecrets = sessionBearer
      ? { bearerBySourceId: { ...sessionSecrets.bearerBySourceId, [source.id]: sessionBearer } }
      : sessionSecrets;
    setSessionSecrets(nextSecrets);
    void upsertSource(db, source).then(async () => {
      const next = await listSources(db);
      setSources(next);
      await refreshExternal(next, nextSecrets);
      host.notifications.notify({ title: t('notify.residentAdded.title'), body: t('notify.residentAdded.body', { name: source.name }), level: 'success' });
    });
  }, [db, host.notifications, refreshExternal, sessionSecrets]);

  const removeSource = useCallback((sourceId: string) => {
    void deleteSource(db, sourceId).then(async () => {
      setSources(await listSources(db));
      setExternalAgents((prev) => prev.filter((a) => a.sourceId !== sourceId));
      setSessionSecrets((prev) => {
        const next = { ...prev.bearerBySourceId };
        delete next[sourceId];
        return { bearerBySourceId: next };
      });
    });
  }, [db]);

  const probeAgent = useCallback((agent: OpenHouseAgent) => {
    setProbingId(agent.id);
    const done = async () => {
      if (agent.sourceKind === 'tytus-daemon' || agent.sourceKind === 'ail-gateway') {
        const podId = agent.id.replace(/^tytus:/, '');
        const result = await probeTytusPod(agent.id, (path) => host.daemon.callPodEndpoint(podId, path));
        const next = { ...agent, status: result.status, latencyMs: result.latencyMs, lastError: result.lastError, capabilities: result.capabilities };
        setTytusAgents((prev) => prev.map((a) => a.id === agent.id ? next : a));
        await persistProbe(db, next);
      } else {
        const source = sources.find((s) => s.id === agent.sourceId);
        if (source) {
          const next = await probeExternalSource(source, sessionSecrets);
          setExternalAgents((prev) => prev.map((a) => a.id === agent.id ? next : a));
          await persistProbe(db, next);
        }
      }
      setHistory(await listHistory(db));
      setProbingId(null);
    };
    void done().catch((err) => {
      host.notifications.notify({ title: t('notify.probeFailed.title'), body: err instanceof Error ? err.message : String(err), level: 'error' });
      setProbingId(null);
    });
  }, [db, host.daemon, host.notifications, sessionSecrets, sources]);

  const copyDiagnostic = useCallback((agent: OpenHouseAgent) => {
    const payload = JSON.stringify({ id: agent.id, source: agent.sourceKind, status: agent.status, room: agent.room, endpoint: agent.endpointHost, capabilities: agent.capabilities, lastError: agent.lastError, raw: agent.raw }, null, 2);
    void navigator.clipboard?.writeText(payload).then(() => host.notifications.notify({ title: t('notify.diagnosticCopied.title'), body: agent.displayName, level: 'success' }));
  }, [host.notifications, t]);

  const copyAgentContract = useCallback((agent: OpenHouseAgent) => {
    const contract = integrationContract(agent);
    void navigator.clipboard?.writeText(contract).then(() => host.notifications.notify({ title: t('notify.contractCopied.title'), body: agent.displayName, level: 'success' }));
  }, [host.notifications, t]);

  const counts = countStatuses(allAgents);
  return <div className="oh-root">
    <style>{styles}</style>
    <div className="oh-top">
      <section className="oh-game-column">
        <HouseScene agents={visibleAgents} savedLayout={[]} selectedId={selected?.id} onSelect={setSelectedId} t={t} />
        <nav className="oh-toolbar" aria-label={t('toolbar.aria')}>
          <label>{t('toolbar.view')}</label>
          <select value={filter} onChange={(e) => setFilter(e.target.value as Filter)}>
            <option value="all">{t('filter.all')}</option>
            <option value="tytus-daemon">{t('filter.tytusPods')}</option>
            <option value="ail-gateway">{t('filter.ailGateway')}</option>
            <option value="openai-compatible">{t('filter.openaiCompatible')}</option>
            <option value="custom-health">{t('filter.healthChecks')}</option>
            <option value="openhouse-probe">{t('filter.openHouseAgents')}</option>
            <option value="mcp-http">{t('filter.mcpLibrary')}</option>
            <option value="online">{t('filter.online')}</option>
            <option value="issues">{t('filter.issues')}</option>
          </select>
          <button type="button" onClick={() => setAddOpen(true)}><Plus size={14} /> {t('action.addAgent')}</button>
          <button type="button" onClick={() => void refreshExternal()} disabled={refreshing}><RefreshCw size={14} /> {refreshing ? t('action.refreshing') : t('action.refreshExternal')}</button>
          <span className="spacer" />
          <span className="counter">{t('counter.residents', { count: allAgents.length })}</span>
          <span className="counter">{t('counter.online', { count: counts.online })}</span>
          <span className="counter">{t('counter.issues', { count: counts.issues })}</span>
        </nav>
      </section>
      <aside className="oh-side">
        <div className="oh-side-head"><p>OpenHouse</p><h2>{selected?.displayName ?? t('side.noResident')}</h2></div>
        {selected ? <div className="oh-side-body">
          <div className={`oh-side-card ${isIssue(selected) ? 'oh-error' : ''}`}>
            <h3>{selected.status.toUpperCase()}</h3>
            <dl>
              <dt>{t('field.room')}</dt><dd>{labelRoom(selected.room)}</dd>
              <dt>{t('field.source')}</dt><dd>{sourceLabel(selected.sourceKind, t)}</dd>
              <dt>{t('field.endpoint')}</dt><dd>{selected.endpointHost ?? '—'}</dd>
              <dt>{t('field.latency')}</dt><dd>{selected.latencyMs ? `${selected.latencyMs}ms` : '—'}</dd>
              <dt>{t('field.lastSeen')}</dt><dd>{selected.lastSeenAt ? new Date(selected.lastSeenAt).toLocaleTimeString() : '—'}</dd>
            </dl>
          </div>
          <div className="oh-side-card"><h3>{t('section.canDo')}</h3><div className="oh-abilities">{selectedAbilities.map((ability) => <div key={ability.title} className="oh-ability"><strong>{ability.title}</strong><span>{ability.body}</span></div>)}</div></div>
          <div className="oh-side-card"><h3>{t('section.capabilities')}</h3><div className="oh-caps">{capabilityBadges(selected.capabilities, t).map((c) => <span key={c}>{c}</span>)}</div></div>
          {selected.lastError && <div className="oh-side-card oh-error"><h3>{t('section.error')}</h3><p>{selected.lastError}</p></div>}
          <div className="oh-actions">
            <button type="button" onClick={() => probeAgent(selected)} disabled={probingId === selected.id}>{probingId === selected.id ? t('action.testing') : t('action.testConnection')}</button>
            <button type="button" onClick={() => copyAgentContract(selected)}>{t('action.copyAgentContract')}</button>
            <button type="button" onClick={() => copyDiagnostic(selected)}>{t('action.copyDiagnostic')}</button>
            {selected.sourceKind !== 'tytus-daemon' && selected.sourceKind !== 'ail-gateway' && <button type="button" onClick={() => removeSource(selected.sourceId)}>{t('action.removeSource')}</button>}
          </div>
          {!!selectedHistory.length && <div className="oh-side-card oh-history"><h3>{t('section.probeHistory')}</h3>{selectedHistory.map((h) => <p key={h.id}><b>{h.status}</b> {h.latencyMs ? `${h.latencyMs}ms` : ''} <span>{new Date(h.createdAt).toLocaleTimeString()}</span></p>)}</div>}
        </div> : <div className="oh-side-body"><div className="oh-side-card">{t('empty.office')}</div></div>}
      </aside>
    </div>
    <section className="oh-bottom">
      <article className="oh-panel oh-memo"><div className="oh-panel-title">{t('memo.title')}</div><p>{counts.issues ? t('memo.issues', { count: counts.issues }) : t('memo.calm')}</p></article>
      <article className="oh-panel oh-playbook"><div className="oh-panel-title">{t('actions.title')}</div><div className="oh-status-grid"><button onClick={() => setFilter('all')}>{t('actions.all')}</button><button onClick={() => setFilter('online')}>{t('actions.working')}</button><button onClick={() => setFilter('issues')}>{t('actions.alert')}</button><button onClick={() => setFilter('ail-gateway')}>{t('actions.ail')}</button></div><p>{t('actions.protocol')}</p></article>
      <article className="oh-panel"><div className="oh-panel-title">{t('visitors.title')}</div><div className="oh-visitor-list">{allAgents.map((agent) => <div className="oh-visitor" key={agent.id}><div><strong>{agent.displayName}</strong><small>{agent.status} · {sourceLabel(agent.sourceKind, t)}</small><div className="oh-mini-caps">{capabilityBadges(agent.capabilities, t).slice(0, 3).map((cap) => <span key={cap}>{cap}</span>)}</div></div><button onClick={() => setSelectedId(agent.id)}>{t('action.focus')}</button><button onClick={() => probeAgent(agent)}>{t('action.probe')}</button></div>)}</div></article>
    </section>
    <AddAgentDialog open={addOpen} onClose={() => setAddOpen(false)} onAdd={addSource} t={t} />
  </div>;
}

async function persistProbe(db: AppDb, agent: OpenHouseAgent): Promise<void> {
  await addHistory(db, {
    id: `probe-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
    agentId: agent.id,
    sourceId: agent.sourceId,
    status: agent.status,
    latencyMs: agent.latencyMs ?? null,
    error: agent.lastError ?? null,
    createdAt: Date.now(),
  });
}

function chunks<T>(items: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

function isIssue(agent: OpenHouseAgent): boolean {
  return agent.status === 'error' || agent.status === 'offline' || agent.status === 'degraded';
}

function countStatuses(agents: OpenHouseAgent[]) {
  const issues = agents.filter(isIssue).length;
  const online = agents.filter((a) => a.status === 'online' || a.status === 'busy').length;
  return { issues, online };
}

function labelRoom(room: string): string {
  return room.replace(/-/g, ' ');
}

function sourceLabel(kind: AgentSourceKind, t: TFunction): string {
  switch (kind) {
    case 'tytus-daemon': return t('source.tytusPod');
    case 'ail-gateway': return t('source.ailGateway');
    case 'openai-compatible': return t('source.openaiCompatible');
    case 'custom-health': return t('source.healthService');
    case 'openhouse-probe': return t('source.openHouseAgent');
    case 'mcp-http': return t('source.mcpHttp');
  }
}

function capabilityBadges(capabilities: AgentCapability[], t?: TFunction): string[] {
  const mapped = capabilities.map((cap) => {
    switch (cap) {
      case 'models': return t ? t('capability.models') : 'models';
      case 'chat': return t ? t('capability.chat') : 'chat';
      case 'tools': return t ? t('capability.tools') : 'tools';
      case 'files': return t ? t('capability.files') : 'files';
      case 'health': return t ? t('capability.health') : 'health';
      case 'mcp': return t ? t('capability.mcp') : 'mcp';
      case 'music': return t ? t('capability.music') : 'music';
      default: return t ? t('capability.unknown') : 'unknown';
    }
  });
  return mapped.length ? Array.from(new Set(mapped)) : [t ? t('capability.unknown') : 'unknown'];
}

function agentAbilities(agent: OpenHouseAgent, t: TFunction): AbilityCard[] {
  const base: Record<AgentSourceKind, AbilityCard[]> = {
    'tytus-daemon': [
      { title: t('ability.tytusWork.title'), body: t('ability.tytusWork.body') },
      { title: t('ability.podEndpoint.title'), body: t('ability.podEndpoint.body') },
    ],
    'ail-gateway': [
      { title: t('ability.modelGateway.title'), body: t('ability.modelGateway.body') },
      { title: t('ability.providerRouting.title'), body: t('ability.providerRouting.body') },
    ],
    'openai-compatible': [
      { title: t('ability.listModels.title'), body: t('ability.listModels.body') },
      { title: t('ability.chatCapable.title'), body: t('ability.chatCapable.body') },
    ],
    'custom-health': [
      { title: t('ability.healthHeartbeat.title'), body: t('ability.healthHeartbeat.body') },
      { title: t('ability.opsMonitor.title'), body: t('ability.opsMonitor.body') },
    ],
    'openhouse-probe': [
      { title: t('ability.residentCard.title'), body: t('ability.residentCard.body') },
      { title: t('ability.thirdAgentNative.title'), body: t('ability.thirdAgentNative.body') },
    ],
    'mcp-http': [
      { title: t('ability.toolLibrary.title'), body: t('ability.toolLibrary.body') },
      { title: t('ability.probeBridge.title'), body: t('ability.probeBridge.body') },
    ],
  };
  const extras: AbilityCard[] = [];
  const caps = new Set(agent.capabilities);
  if (caps.has('tools')) extras.push({ title: t('ability.useTools.title'), body: t('ability.useTools.body') });
  if (caps.has('files')) extras.push({ title: t('ability.useFiles.title'), body: t('ability.useFiles.body') });
  if (caps.has('mcp')) extras.push({ title: t('ability.mcpProtocol.title'), body: t('ability.mcpProtocol.body') });
  if (caps.has('music')) extras.push({ title: t('ability.musicMedia.title'), body: t('ability.musicMedia.body') });
  return [...base[agent.sourceKind], ...extras].slice(0, 5);
}

function integrationContract(agent: OpenHouseAgent): string {
  if (agent.sourceKind === 'openhouse-probe') {
    return `GET /.well-known/openhouse-agent.json\n{\n  "id": "${agent.id}",\n  "name": "${agent.displayName}",\n  "status": "online",\n  "capabilities": ["health", "tools"],\n  "mood": "focused"\n}`;
  }
  if (agent.sourceKind === 'openai-compatible' || agent.sourceKind === 'ail-gateway') {
    return 'OpenAI-compatible contract:\nGET /v1/models\nPOST /v1/chat/completions (for workers that need chat)';
  }
  if (agent.sourceKind === 'mcp-http') return 'MCP contract:\nGET /.well-known/mcp or GET /health\nExpose tools/resources/prompts via MCP HTTP/SSE.';
  if (agent.sourceKind === 'custom-health') return 'Health contract:\nGET /health -> { "status": "ok", "name": "agent-name", "capabilities": ["health"] }';
  return 'Tytus pod contract:\nhost.daemon.state.agents + host.daemon.state.included\nhost.daemon.callPodEndpoint(podId, path) for live checks.';
}
